('93faeaa9-58b7-5d7f-af63-396b846ec633', (select id from categories where name = 'Edebiyat'), 'ku-kmr', 'Cureyê wêjeyî yê ku tê de jiyana kesekî navdar ji aliyê kesekî din ve tê vegotin, çawa tê binavkirin?', 'Otobiyografî', 'Biyografî', 'Kurtejiyan', 'Bîranîn', 'B', 'Biyografî qalkirina jiyana kesekî ye ji aliyê kesekî sêyemîn ve; heger mirov jiyana xwe binivîse dibe otobiyografî.', 'Biyografî qalkirina jiyana kesekî ye ji aliyê kesekî sêyemîn ve; heger mirov jiyana xwe binivîse dibe otobiyografî.', 'Biyografi birinin yaşamının üçüncü bir kişi tarafından anlatılmasıdır; kişi kendi hayatını yazarsa otobiyografi olur.', 2, true, 'multiple_choice', NULL, NULL, 'Yeni sorular 2026-11-07 (çapraz inceleme)', NULL, 'approved', 'Kurmancî', 2, now()),
